fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // Number of test cases
    let t = input[0] as usize;
    let mut answers = Vec::with_capacity(t);

    // Helper to detect powers of two
    fn is_power_of_two(x: u64) -> bool {
        x != 0 && (x & (x - 1)) == 0
    }

    for i in 0..t {
        let n = input[i + 1] as u64;
        let winner = if n == 1 {
            "FastestFinger"
        } else if n == 2 {
            "Ashishgup"
        } else if is_power_of_two(n) {
            // All powers of two > 2
            "FastestFinger"
        } else if n % 4 != 2 {
            // Includes all odd n and those divisible by 4
            "Ashishgup"
        } else {
            // n % 4 == 2 case
            let p = n / 2;
            // limited-prime as per problem statement:
            // p <= 1 => not prime
            // p == 2 => prime
            // any even p > 2 => not prime
            // any odd p > 2 => treated as prime
            let is_limited_prime = if p <= 1 {
                false
            } else if p == 2 {
                true
            } else if p % 2 == 0 {
                false
            } else {
                true
            };

            if is_limited_prime {
                "FastestFinger"
            } else {
                "Ashishgup"
            }
        };

        answers.push(winner);
    }

    answers
}